import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] adjMatrix = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                adjMatrix[i][j] = sc.nextInt();
            }
        }

        for (int i = 0; i < n; i++) {
            boolean f = false;
            for (int j = 0; j < n; j++) {
                if (adjMatrix[i][j] == 1) {
                    if (f) {
                        System.out.print(" ");
                    }
                    System.out.print(j + 1);
                    f = true;
                }
            }
            System.out.println();
        }

        sc.close();
    }
}
